"""Interview problems 28-51 (logic, counting, number theory). Numbers verified below."""
import math
from iq_helpers import *

assert sum(k * k for k in range(1, 9)) == 204
assert (100 - 64) * 2 + 1 == 73
assert 100 // 5 + 100 // 25 == 24
assert pow(7, 100, 10) == 1 and pow(2, 100, 7) == 2
assert math.gcd(1071, 462) == 21
assert len([n for n in range(2, 101) if all(n % d for d in range(2, int(n ** 0.5) + 1))]) == 25
assert len(str(math.factorial(100))) == 158
assert 2 ** 3 * 3 ** 2 * 5 == 360 and 4 * 3 * 2 == 24
assert [x for x in range(1, 1000) if x % 3 == 2 and x % 5 == 3 and x % 7 == 2][0] == 23
assert sum(str(n).count("9") for n in range(1, 101)) == 20
assert 3 ** 6 < 1000 <= 3 ** 7

